"import os

def w(path, text):
    d = os.path.dirname(path)
    if d:
        os.makedirs(d, exist_ok=True)
    with open(path, "w") as f:
        f.write(text)

# Domain and physics
LX, LY, LZ = 9.0, 1.0, 2.0
T_HOT, T_COLD = 301.0, 300.0
